const data = $json.body;
console.log('Incoming form data:', JSON.stringify(data, null, 2));
return [{
  json: {
    departurePort:       data.departurePort       || 'Not specified',
    cruiseRegion:        data.cruiseRegion         || 'Not specified',
    startDate:           data.startDate            || 'N/A',
    endDate:             data.endDate              || 'N/A',
    cruiseDuration:      data.cruiseDuration       || 'Not specified',
    tripType:            data.tripType             || 'N/A',
    onboardPreferences:  data.onboardPreferences   || [],
    shoreExcursions:     data.shoreExcursions      || [],
    cabinType:           data.cabinType            || 'Not specified',
    groupSize:           data.groupSize            || '1',
    ageRange:            data.ageRange             || [],
    dietaryNeeds:        data.dietaryNeeds         || 'None',
    specialOccasion:     data.specialOccasion      || 'None',
    budget:              data.budget               || '0',
    email:               data.email                || ''
  }
}];

const {
  departurePort, cruiseRegion, startDate, endDate, cruiseDuration,
  tripType, onboardPreferences, shoreExcursions, cabinType, groupSize,
  ageRange, dietaryNeeds, specialOccasion, budget, email
} = $json;

const prefStr    = Array.isArray(onboardPreferences) ? onboardPreferences.join(', ') : onboardPreferences || 'Not specified';
const shoreStr   = Array.isArray(shoreExcursions)    ? shoreExcursions.join(', ')    : shoreExcursions    || 'Not specified';
const ageStr     = Array.isArray(ageRange)           ? ageRange.join(', ')           : ageRange           || 'Not specified';

const prompt = `You are an experienced AI travel agent specializing in cruise trips. Create a complete, exciting, and well-organized cruise itinerary based on the following details:

- Departure Port: ${departurePort}
- Cruise Region / Destination: ${cruiseRegion}
- Travel Dates: ${startDate} to ${endDate}
- Cruise Duration: ${cruiseDuration} nights
- Trip Type: ${tripType}
- Group Size: ${groupSize}
- Age Ranges in Group: ${ageStr}
- Cabin Type: ${cabinType}
- Onboard Preferences: ${prefStr}
- Shore Excursion Interests: ${shoreStr}
- Dietary Needs: ${dietaryNeeds}
- Special Occasion: ${specialOccasion}
- Budget: $${budget}

Create a complete itinerary including:
1. Recommended cruise lines and ships (specific options departing from ${departurePort} to ${cruiseRegion}, matching the duration and group preferences)
2. Onboard activities tailored to the listed preferences, with estimated costs where applicable
3. Shore excursions at each port of call matching the shore excursion interests, with estimated costs and booking links
4. A day-by-day schedule covering embarkation through disembarkation, with morning/afternoon/evening activities, dining options, and ports of call
5. Dining recommendations including specialty restaurants and budget tips, accounting for dietary needs: ${dietaryNeeds}
6. Estimated food and extras budget per person per day
7. A Cost Summary table (mandatory — always include even if estimates). Categories in order: Cruise Fare, Onboard Activities, Shore Excursions, Food, Total, Remaining Budget. Format as tab-separated (e.g. Cruise Fare\t$1,000)
8. Practical travel tips specific to ${cruiseRegion} and this type of voyage${specialOccasion !== 'None' ? ', plus special occasion suggestions for the ' + specialOccasion : ''}

Format rules:
- No Markdown (no ###, **, or | table syntax)
- Section headings end with a colon (e.g. "Cruise Lines and Ships:")
- Bullet points use a hyphen: - item
- Use <strong> tags for Day labels in the Daily Schedule (e.g. <strong>Day 1: Embarkation in ${departurePort}</strong>)
- Use <strong> for Total and Remaining Budget rows in the Cost Summary
- Include real, clickable <a href="URL">anchor text</a> links for booking cruise lines, excursions, and activities — no placeholder URLs
- Add relevant emojis sparingly to improve readability`;

return [{
  json: {
    email, cruiseRegion, startDate, endDate, cruiseDuration,
    tripType, onboardPreferences, shoreExcursions, cabinType,
    groupSize, ageRange, dietaryNeeds, specialOccasion,
    budget, departurePort, prompt
  }
}];

const cruise = $node['Prepare Cruise Data'].json;
const ai = $node['OpenAI'].json.message?.content || 'No itinerary found.';
console.log('Raw OpenAI output (first 500 chars):', ai.substring(0, 500));
return [{
  json: {
    departurePort:      cruise.departurePort,
    cruiseRegion:       cruise.cruiseRegion,
    startDate:          cruise.startDate,
    endDate:            cruise.endDate,
    cruiseDuration:     cruise.cruiseDuration,
    tripType:           cruise.tripType,
    onboardPreferences: cruise.onboardPreferences,
    shoreExcursions:    cruise.shoreExcursions,
    cabinType:          cruise.cabinType,
    groupSize:          cruise.groupSize,
    ageRange:           cruise.ageRange,
    dietaryNeeds:       cruise.dietaryNeeds,
    specialOccasion:    cruise.specialOccasion,
    budget:             cruise.budget,
    email:              cruise.email,
    itinerary:          ai
  }
}];

const destination      = $json.cruiseRegion       || 'Your Destination';
const departurePort    = $json.departurePort      || 'Not specified';
const travelDates      = `${$json.startDate || 'N/A'} to ${$json.endDate || 'N/A'}`;
const cruiseDuration   = $json.cruiseDuration     || 'Not specified';
const budget           = $json.budget             || 'N/A';
const groupSize        = $json.groupSize          || 'N/A';
const tripType         = $json.tripType           || 'N/A';
const cabinType        = $json.cabinType          || 'Not specified';
const onboardPrefs     = Array.isArray($json.onboardPreferences) ? $json.onboardPreferences.join(', ') : $json.onboardPreferences || 'Not specified';
const shoreExc         = Array.isArray($json.shoreExcursions)    ? $json.shoreExcursions.join(', ')    : $json.shoreExcursions    || 'Not specified';
const ageRange         = Array.isArray($json.ageRange)           ? $json.ageRange.join(', ')           : $json.ageRange           || 'Not specified';
const dietaryNeeds     = $json.dietaryNeeds       || 'None';
const specialOccasion  = $json.specialOccasion    || 'None';
const itineraryContent = $json.itinerary          || 'Itinerary details not available.';

// ── Email HTML (Voyage Genie brand: #023e8a header) ──
const metaRow = (label, value) =>
  `<p style="color:#333;font-size:15px;margin:8px 0;line-height:1.5;"><strong style="color:#023e8a;">${label}:</strong> ${value}</p>`;

const emailHtml = `
<div style="font-family:'Helvetica Neue',Arial,sans-serif;max-width:640px;margin:0 auto;background:#f8fafc;padding:24px;border-radius:12px;">
  <div style="background:linear-gradient(105deg,#023e8a,#0077b6);padding:24px 28px;border-radius:10px 10px 0 0;text-align:center;">
    <h1 style="color:#ffffff;margin:0;font-size:26px;font-family:Georgia,serif;">🚢 Your Cruise Itinerary</h1>
    <p style="color:rgba(255,255,255,0.8);margin:6px 0 0;font-size:14px;">Generated by Voyage Genie</p>
  </div>
  <div style="background:#ffffff;padding:28px;border-radius:0 0 10px 10px;border:1px solid #e2e8f0;border-top:none;">
    <h2 style="color:#023e8a;font-size:18px;margin:0 0 16px;border-bottom:2px solid #eaf4fb;padding-bottom:10px;">Trip Overview</h2>
    ${metaRow('⚓ Departing from', departurePort)}
    ${metaRow('🌍 Cruise Region', destination)}
    ${metaRow('📅 Travel Dates', travelDates)}
    ${metaRow('⏳ Duration', cruiseDuration + ' nights')}
    ${metaRow('🛏️ Cabin Type', cabinType)}
    ${metaRow('🧳 Trip Type', tripType)}
    ${metaRow('👥 Group Size', groupSize + ' traveler(s)')}
    ${metaRow('👨‍👩‍👧 Age Ranges', ageRange)}
    ${metaRow('🎉 Onboard Preferences', onboardPrefs)}
    ${metaRow('🏝️ Shore Excursion Interests', shoreExc)}
    ${dietaryNeeds !== 'None' ? metaRow('🍽️ Dietary Needs', dietaryNeeds) : ''}
    ${specialOccasion !== 'None' ? metaRow('🎂 Special Occasion', specialOccasion) : ''}
    ${metaRow('💵 Budget', '$' + budget)}
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:20px 0;">
    <h3 style="color:#023e8a;font-size:16px;margin:0 0 14px;">Your Itinerary Details</h3>
    <div style="background:#f8fafc;padding:20px;border-radius:8px;font-size:14px;line-height:1.7;color:#1e293b;border:1px solid #e2e8f0;">
      ${itineraryContent}
    </div>
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:24px 0 16px;">
    <p style="color:#64748b;font-size:12px;text-align:center;margin:0;">
      Generated by <strong>Voyage Genie</strong> 🌟 &nbsp;|&nbsp; Plan Less, Explore More
    </p>
  </div>
</div>`;

const sessionId = Date.now().toString();
const subject   = `Your Cruise Itinerary for ${destination} – Voyage Genie`;

// ── Full formData for frontend trip-summary strip ──
const formData = {
  departurePort:      departurePort,
  cruiseRegion:       destination,
  startDate:          $json.startDate    || '',
  endDate:            $json.endDate      || '',
  cruiseDuration:     cruiseDuration,
  tripType:           tripType,
  cabinType:          cabinType,
  groupSize:          groupSize,
  budget:             budget,
  onboardPreferences: $json.onboardPreferences || [],
  shoreExcursions:    $json.shoreExcursions    || [],
  ageRange:           $json.ageRange           || [],
  dietaryNeeds:       dietaryNeeds,
  specialOccasion:    specialOccasion
};

console.log('Resolved email for:', $json.email, '| sessionId:', sessionId);

return [{
  json: {
    sessionId,
    itineraryHtml:   emailHtml,
    resolvedEmail:   $json.email || '',
    resolvedSubject: subject,
    resolvedMessage: emailHtml,
    formData
  }
}];

console.log('Request Details:', JSON.stringify($json, null, 2));
let method = $json.method;
if (!method) {
  method = $json.headers[':method'] || 'POST';
}
return [{ json: { ...$json, method: method } }];

// ── Extract raw AI output ──
const itineraryRaw = $node['OpenAI'].json.message?.content || 'No itinerary found.';
console.log('Raw OpenAI output (first 300 chars):', itineraryRaw.substring(0, 300));

const HEADING_COLOR = '#023e8a'; // Voyage Genie brand navy
const HEADING_STYLE = `font-size:16px;color:${HEADING_COLOR};display:block;margin:18px 0 6px 0;font-weight:600;`;
const TABLE_CELL    = 'border:1px solid #e2e8f0;padding:9px 12px;font-size:14px;';
const TABLE_BOLD    = 'border:1px solid #e2e8f0;padding:9px 12px;font-size:14px;background:#eaf4fb;font-weight:600;color:#023e8a;';

const lines = itineraryRaw.split('\n');
let html = '';
let inCostSummary = false;
let inDailySchedule = false;
let costRows = [];
let scheduleLines = [];

// Helper: flush the cost summary table
function flushCostTable() {
  if (costRows.length === 0) return '';
  const rows = costRows.join('');
  costRows = [];
  return `<table style="border-collapse:collapse;width:100%;margin:12px 0;" cellpadding="0" cellspacing="0">${rows}</table><br>`;
}

// Helper: format a collected daily schedule block
function flushDailySchedule(schedLines) {
  let out = `<strong style="${HEADING_STYLE}">Daily Schedule:</strong>`;
  const joined = schedLines.join('\n');
  // Match each Day block
  const dayBlocks = joined.split(/(?=<strong>Day \d+:)/);
  for (const block of dayBlocks) {
    if (!block.trim()) continue;
    // Already has <strong> tags from AI — just wrap bullet items
    const bulletLines = block.split('\n').map(l => {
      const t = l.trim();
      if (!t) return '';
      if (t.startsWith('<strong>')) return t + '<br>';
      if (t.startsWith('- ')) return `<span style="display:block;padding-left:1em;">${t}</span>`;
      return t + '<br>';
    });
    out += bulletLines.join('');
  }
  return out + '<br>';
}

for (let i = 0; i < lines.length; i++) {
  const raw = lines[i];
  const line = raw.trim();

  // Blank line
  if (!line) {
    if (inCostSummary) {
      html += flushCostTable();
      inCostSummary = false;
    } else if (inDailySchedule) {
      html += flushDailySchedule(scheduleLines);
      inDailySchedule = false;
      scheduleLines = [];
    } else {
      html += '<br>';
    }
    continue;
  }

  const lower = line.toLowerCase();

  // ── Daily Schedule section ──
  if (lower.startsWith('daily schedule:')) {
    inDailySchedule = true;
    scheduleLines = [];
    continue;
  }
  if (inDailySchedule) {
    scheduleLines.push(line);
    continue;
  }

  // ── Cost Summary section ──
  if (lower.startsWith('cost summary:')) {
    html += `<strong style="${HEADING_STYLE}">Cost Summary:</strong>`;
    inCostSummary = true;
    costRows = [];
    continue;
  }
  if (inCostSummary) {
    if (line.includes('\t')) {
      const parts = line.split('\t').map(s => s.trim());
      const cat  = parts[0] || '';
      const cost = parts[1] || '';
      const isTotals = cat.replace(/<[^>]+>/g,'').match(/^(Total|Remaining Budget)/i);
      const style = isTotals ? TABLE_BOLD : TABLE_CELL;
      costRows.push(`<tr><td style="${style}">${cat}</td><td style="${style}">${cost}</td></tr>`);
      continue;
    } else {
      // Non-tab line closes the table
      html += flushCostTable();
      inCostSummary = false;
      // Fall through to render this line normally
    }
  }

  // ── Section headings (end with colon, no inline tags) ──
  if (line.endsWith(':') && !line.includes('<')) {
    html += `<strong style="${HEADING_STYLE}">${line}</strong>`;
    continue;
  }

  // ── Bullet points ──
  if (line.startsWith('- ')) {
    html += `<span style="display:block;padding-left:1em;">${line}</span>`;
    continue;
  }

  // ── Everything else ──
  html += line + '<br>';
}

// Flush anything still open at end of input
if (inCostSummary) html += flushCostTable();
if (inDailySchedule) html += flushDailySchedule(scheduleLines);

// Ensure Cost Summary is present (fallback)
const budget = $json.budget || '0';
if (!html.toLowerCase().includes('cost summary:')) {
  html += `<strong style="${HEADING_STYLE}">Cost Summary:</strong>`;
  html += `<table style="border-collapse:collapse;width:100%;margin:12px 0;" cellpadding="0" cellspacing="0">
    <tr><td style="${TABLE_CELL}">Cruise Fare</td><td style="${TABLE_CELL}">$0</td></tr>
    <tr><td style="${TABLE_CELL}">Onboard Activities</td><td style="${TABLE_CELL}">$0</td></tr>
    <tr><td style="${TABLE_CELL}">Shore Excursions</td><td style="${TABLE_CELL}">$0</td></tr>
    <tr><td style="${TABLE_CELL}">Food</td><td style="${TABLE_CELL}">$0</td></tr>
    <tr><td style="${TABLE_BOLD}">Total</td><td style="${TABLE_BOLD}">$0</td></tr>
    <tr><td style="${TABLE_BOLD}">Remaining Budget</td><td style="${TABLE_BOLD}">$${budget}</td></tr>
  </table><br>`;
}

console.log('Formatted itinerary HTML (first 500 chars):', html.substring(0, 500));

return [{ json: { ...$json, itinerary: html } }];
